    "note_pins_label": "Macho vs Hembra",
    "note_pins": "Los conectores machos tienen pines guía; los hembras tienen orificios para pines guía. Los transceptores usan MPO hembra; los cables de parcheo suelen ser macho a hembra.",
    "breakout_type": "Configuración Breakout",
