    "fiber_color_note": "Las posiciones 13–24 repiten los mismos 12 colores. La identificación física usa una franja o anillo negro alrededor del segundo grupo de 12 fibras.",
    "wiring_std": "Estándar de Cableado",
    "cable_type": "Tipo de Cable",
