    "step1_title": "1. Genere un par de llaves en su estación de trabajo",
    "step1_body": "Use el Keypair Generator a continuación para construir el comando ssh-keygen. Esto crea una private key (nunca la comparta) y un archivo .pub que contiene su public key.",
    "step2_title": "2. Autorice la public key en cada dispositivo",
    "step2_body": "Pegue su public key en la configuración del dispositivo usando los comandos específicos del fabricante en la sección Device Provisioning al final de esta página.",
    "step3_title": "3. Configure este formulario y luego despliegue la Config generada",
    "step3_body": "Establezca IdentityFile con la ruta de su private key, elija un Vendor Preset para rellenar los ajustes de Ciphers/KEX, complete los Alias y Hostnames, luego exporte a ~/.ssh/config.",
    "how_to_use_note": "El archivo ~/.ssh/config debe tener chmod 600. Su archivo de private key también debe tener chmod 600. El archivo .pub es seguro de copiar libremente.",
    "keygen_title": "Keypair Generator",
    "keygen_subtitle": "Construya el comando ssh-keygen para su estación de trabajo. Se prefiere Ed25519 para todos los dispositivos modernos.",
    "key_type": "Tipo de clave",
    "key_comment": "Comentario",
    "key_comment_ph": "su-nombre-mgmt",
    "key_filename": "Nombre del archivo de salida",
    "key_filename_ph": "~/.ssh/id_net_mgmt",
    "keygen_command": "Comando Keygen",
    "keygen_hint": "Ejecute esto en su estación de trabajo. Nunca comparta el archivo de private key — solo distribuya el archivo .pub a los dispositivos.",
    "provision_title": "Aprovisionamiento de dispositivos",
    "provision_subtitle": "Autorice su public key en el dispositivo de destino. Pegue el contenido de su archivo .pub a continuación para obtener un fragmento listo para aplicar.",
    "provision_username": "Nombre de usuario en el dispositivo",
    "provision_pubkey_label": "Su clave pública (contenido del archivo .pub)",
    "provision_pubkey_ph": "ssh-ed25519 AAAA... su-nombre-mgmt",
    "provision_pubkey_hint": "Opcional — pegue el contenido completo de su archivo .pub para generar un fragmento completo listo para pegar.",
    "provision_note_ios": "Cisco iOS requiere la public key en trozos de 254 caracteres o menos. Al pegar su llave arriba, se dividirá automáticamente. Sin una llave, el marcador de posición debe envolverse manualmente.",
    "provision_snippet_label": "Fragmento de configuración del dispositivo",
    "ref_title": "Referencia Rápida",
    "ref_subtitle": "Patrones SSH comunes — línea de comandos y la entrada equivalente en ~/.ssh/config.",
    "ref_s2s_title": "SSH de Servidor a Servidor",
