    "strat_reno": "Aumento Aditivo / Disminución Multiplicativa (AIMD)",
    "strat_cubic": "Función cúbica — agresiva en redes de alto BDP",
    "strat_bbr": "Basado en modelo — estima ancho de banda y RTT",
    "loss_resp_reno": "cwnd se reduce a la mitad en caso de pérdida; el timeout restablece a 1 MSS",
    "loss_resp_cubic": "cwnd *= 0.7; recuperación cóncavo-convexa mediante W(t) = C(t-K)^3 + Wmax",
    "loss_resp_bbr": "Ignora la pérdida; continúa a la tasa BDP estimada",
    "loss_impact_title": "Análisis de Impacto de Pérdida",
    "loss_impact_hint": "Con la tasa de pérdida configurada, cada algoritmo responde de manera diferente. BBR es tolerante a pérdidas por diseño.",
    "recovery_reno": "AIMD: reducir cwnd a la mitad, recrecimiento lineal",
    "recovery_cubic": "Recuperación más rápida mediante función cúbica",
    "recovery_bbr": "No requiere recuperación (tolerante a pérdidas)",
    "notes_reno": "Conservador; más lento en recuperarse en rutas de alto BDP",
    "notes_cubic": "Mejor en LFNs; por defecto en Linux desde el kernel 2.6.19",
    "notes_bbr": "Mejor rendimiento bajo pérdida; puede causar colas si no se ajusta",
    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "Ajuste de TCP en Linux (sysctl)",
    "sysctl_subtitle": "Genere comandos sysctl para ajustar los buffers de TCP y el control de congestión de Linux para los parámetros de su ruta.",
    "sysctl_algo": "Algoritmo de Control de Congestion",
    "sysctl_apply_hint": "Aplicar con: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Los valores se calculan a partir de su BDP.",
    "ref_title": "Referencia de Algoritmo",
    "ref_reno_desc": "Algoritmo AIMD clásico. Slow start duplica cwnd cada RTT hasta ssthresh. Congestion avoidance añade ~1 segmento por RTT. Con 3 ACKs duplicados: ssthresh = cwnd/2, cwnd = ssthresh. En timeout: cwnd = 1 MSS. Justo pero subutiliza rutas de alto BDP tras pérdida.",
    "ref_cubic_desc": "Por defecto en Linux. Utiliza una función cúbica W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7). Tras pérdida, cwnd cae al 70% de W_max, luego crece mediante la curva cóncavo-convexa. Más agresivo que Reno en long-fat networks. K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "Algoritmo basado en modelo de Google. Estima el ancho de banda del cuello de botella y el RTT mínimo en lugar de usar la pérdida como señal. Fases: Startup (2.89x ganancia), Drain, ProbeBW (ciclo de ganancia de 8 fases: 1.25/0.75/1...), ProbeRTT (4 segmentos cada ~10s). Logra rendimiento completo incluso con pérdida.",
    "phase_startup": "Startup",
    "phase_drain": "Drain",
    "phase_probe_bw": "ProbeBW",
    "phase_probe_rtt": "ProbeRTT",
