    "desc_bridge": "Puente de software en el host de Docker — modo predeterminado. Los contenedores comparten una subred, NAT hacia el exterior. Ideal para aplicaciones de un solo host.",
    "desc_overlay": "Superposición de varios hosts mediante encapsulación VXLAN — requiere Docker Swarm. Los contenedores en diferentes hosts aparecen en el mismo segmento L2.",
