    "plat_iosxe_notes": "Asegúrese de que el sistema de archivos flash tenga espacio libre suficiente con \"show flash:\". Si utiliza SCP, debe configurarse \"ip scp server enable\" en el servidor, o el dispositivo debe tener el enrutamiento SSH habilitado.",
    "plat_iosxr_notes": "Los sistemas de archivos de IOS-XR usan disk0: o disk1: en lugar de flash:. Los comandos SCP/SFTP en XR solicitan la contraseña del usuario de forma interactiva. El contexto de enrutamiento (VRF) puede configurarse globalmente.",
    "plat_nxos_notes": "NX-OS usa bootflash: de forma predeterminada. Verifique el espacio del sistema de archivos con \"dir bootflash:\". El VRF debe tener alcanzabilidad IP al servidor; compruebe el enrutamiento predeterminado o el VRF de gestión.",
    "plat_junos_notes": "Las copias de archivos en Junos se colocan en /var/tmp/ o /var/db/config/. Use \"show system storage\" para comprobar el espacio en disco. Las transferencias TFTP pueden requerir configuraciones del protocolo de enrutamiento de Junos o el uso de la palabra clave routing-instance.",
    "plat_eos_notes": "Los dispositivos Arista usan flash:. Verifíquelo con \"dir flash:\". Para alto rendimiento, Arista admite copias nativas HTTP/HTTPS que están altamente optimizadas.",
    "plat_fortios_notes": "La restauración TFTP de FortiOS reemplaza la imagen de arranque y reinicia el dispositivo automáticamente. Úsela con precaución. Guarde siempre los archivos de configuración de antemano.",
    "plat_panos_notes": "Palo Alto PAN-OS requiere permisos explícitos de administrador CLI para ejecutar comandos de importación de software. El software también puede descargarse directamente de las actualizaciones oficiales de soporte de Palo Alto.",
    "plat_linux_notes": "Verifique los permisos de lectura/escritura del directorio de destino. Asegúrese de que el cliente (scp, curl) esté instalado. Las transferencias HTTP/HTTPS mediante curl/wget son altamente paralelizables.",
    "plat_f5_notes": "Verifique los procesos bigstart y los permisos de ruta administrativa de F5. La carpeta de destino /shared/images/ es la ubicación predeterminada para los archivos ISO de F5.",
    "cmd_iosxe": "! Comando Cisco IOS/IOS-XE",
