    "lb_subghz_note": "Los perfiles Zigbee de 868 MHz (EU) y 915 MHz (US) ofrecen un rango y una penetración de paredes significativamente mejores que los de 2.4 GHz debido a una menor pérdida de trayectoria (ventaja de ~9 dB sobre 2.4 GHz a la misma distancia). Compensación: menor tasa de datos (20–40 kbps frente a 250 kbps) y menos canales.",
