    "title": "Calculadora de NAT/PAT",
    "subtitle": "Traducción de Direcciones IPv4 y Dimensionamiento de Asignación de Bloques de Puertos",
    "network_definition": "Definición de Red",
    "translation_table": "Tabla de Traducción",
    "more_entries": "... {count} traducciones más ...",
