    "remaining": "({count} restantes)",
    "outside_global_sim_hint": "IP de destino para la simulación",
    "randomize_ip": "Aleatorio",
    "double_nat_title": "Doble NAT en despliegues CGNAT",
    "double_nat_body": "En un despliegue típico de CGNAT, los suscriptores también realizan NAT en su CPE — traduciendo direcciones {rfc1918} a su dirección 100.64.0.0/10 asignada antes de que el tráfico llegue al NAT del operador. Esta doble NAT rompe UPnP y el mapeo automático de puertos, complica el reenvío manual de puertos y es un punto crítico conocido para juegos, VoIP y any application que requiera conexiones entrantes.",
    "hosts_hint": "Hosts internos simulados (limitados por el tamaño del pool local)",
    "subscribers_hint": "Suscriptores / CPEs simulados — a cada uno se le asigna un bloque de puertos dedicado del pool público",
    "mode_desc_static": "Vinculación permanente 1:1 — cada host interno se mapea a una IP pública dedicada. Acceso bidireccional habilitado.",
    "mode_desc_dynamic": "Asignación de pool por orden de llegada. Los puertos no se modifican. Las conexiones fallan cuando el pool se agota.",
    "mode_desc_pat": "Todos los hosts internos comparten el pool de IPs públicas mediante una asignación de puertos única. El agotamiento de puertos se muestra como conexiones descartadas.",
