    "desc_strategy_dynamic": "PAT estándar asigna puertos de origen dinámicamente uno por uno a medida que se abren las conexiones. El valor aquí representa el uso pico de puertos modelado por host para estimar la capacidad agregada.",
    "desc_strategy_deterministic": "CGNAT asigna un bloque fijo y reservado de puertos de origen a cada suscriptor de antemano. Esto garantiza la disponibilidad de puertos y reduce la sobrecarga de syslog en un 99% (solo se registra la asignación del bloque, no las sesiones individuales), pero limita el total de suscriptores por IP pública.",
