    "safe_nat_pool": "Seguro (mapeo 1:1 totalmente cubierto).",
    "scenario_label": "Seleccionar escenario de doble NAT",
    "scenario_overlap_title": "Escenario 1: Subredes Solapadas (VPN IPsec)",
    "scenario_overlap_desc": "Dos redes usan el mismo rango privado (ej., 192.168.1.0/24). Para comunicarse sin conflictos de IP, ambas partes deben realizar NAT. El Host A traduce a una IP de tránsito, y el Host B traduce a una IP de tránsito.",
    "scenario_cgnat_title": "Escenario 2: NAT de Nivel de Operador (CGNAT) a NAT de Cliente",
    "scenario_cgnat_desc": "El Proveedor de Servicios asigna 100.64.0.0/10 (RFC 6598) al WAN del Cliente. El Cliente realiza NAT local (192.168.1.0/24 -> 100.64.1.2), y el Proveedor realiza CGNAT (100.64.1.2 -> IP Pública) para conservar espacio IPv4.",
