    "err_invalid_global": "Formato de subred o rango Inside Global inválido",
    "err_invalid_ip": "Formato de dirección IP inválido",
    "explanation_title": "Entendiendo NAT vs. PAT",
    "explanation_intro": "Network Address Translation (NAT) y Port Address Translation (PAT) son técnicas para mapear un espacio de direcciones IP a otro, utilizadas principalmente para preservar las limitadas direcciones IPv4 públicas o resolver conflictos de subred.",
    "nat_expl_title": "1. ¿Qué es NAT?",
    "nat_expl_desc": "NAT traduce direcciones IP en una base 1 a 1. Puede ser Estática (mapeo permanente de una IP privada a una IP pública, ideal para servidores con acceso público) o Dinámica (asigna una IP pública de un pool a un host privado bajo demanda. Una vez que se asignan todas las IPs públicas, los hosts subsiguientes se bloquean hasta que se libere una IP). Los números de puerto no se modifican.",
    "pat_expl_title": "2. ¿Qué es PAT (NAT Overload)?",
    "pat_expl_desc": "PAT (o Port Address Translation / NAT Overload) traduce tanto la dirección IP como el número de puerto de origen en una base muchos a uno (N a 1). Múltiples hosts privados comparten una única dirección IP pública mediante la asignación de puertos de origen únicos (ej. 192.168.1.10:5000 y 192.168.1.11:5000 se mapean a 203.0.113.10:1024 y 203.0.113.10:1025). Este es el método estándar para routers domésticos y acceso a internet empresarial.",
    "comparison_table_title": "Resumen Comparativo",
    "comp_header_feature": "Característica",
    "comp_header_nat": "NAT (1 a 1)",
    "comp_header_pat": "PAT (N a 1 / Overload)",
