    "cheatsheet_intro": "Patrones comunes de comandos iperf3 e iperf2 para pruebas de rendimiento, jitter y pérdida de paquetes.",
    "about_body": "iperf es una herramienta de medición activa para el ancho de banda máximo alcanzable en redes IP. Un host funciona como servidor (oyente) y otro se conecta como cliente para enviar (o recibir) tráfico sobre TCP, UDP o SCTP, informando rendimiento, jitter y pérdida de paquetes. iperf3 (binario iperf3) es una reescritura moderna con salida JSON y modos de reversa/bidireccionales; iperf2 (binario iperf) es multi-cliente y más fuerte para Wi-Fi y multicast. Los dos NO son compatibles a nivel de cable — ambos extremos deben ejecutar la misma versión.",
