    "docker_subtitle": "Ejecute un servidor iperf en Docker — no requiere instalación local.",
    "docker_run_label": "docker run (iperf3)",
    "docker_compose_label": "docker compose",
    "docker_compose_hint": "Guarde como docker-compose.yml, luego ejecute docker compose up -d.",
    "notes_heading": "Notas importantes",
    "note_1": "iperf3 maneja solo un cliente a la vez; ejecute múltiples instancias de iperf3 en diferentes puertos para pruebas concurrentes.",
    "note_2": "El tráfico de control y de datos utilizan el mismo puerto (por defecto 5201 para iperf3, 5001 para iperf2) — abra tanto TCP como UDP en ese puerto en su cortafuegos.",
    "note_3": "Las pruebas UDP requieren un objetivo de ancho de banda explícito con -b; sin él, iperf2 por defecto es 1 Mbit/s e iperf3 también es 1 Mbit/s.",
    "note_4": "iperf2 e iperf3 NO son compatibles — el cliente y el servidor deben ejecutar la misma versión mayor.",
    "note_5": "Para rutas de alto BDP (redes largas y rápidas), aumente la ventana del socket con -w (ej. -w 4M) y use múltiples hilos con -P para saturar el enlace.",
    "title_label": "Título / Comentario"
